struct Proposal {
    address target;
    bytes data;
    uint256 snapshotBlock;
    uint256 voteEnd;
    uint256 forVotes;
    uint256 againstVotes;
    bool executed;
}

function propose(address target, bytes calldata data)
    external returns (uint256 id)
{
    id = proposalCount++;
    proposals[id] = Proposal(
        target, data, block.number,
        block.timestamp + VOTING_PERIOD,
        0, 0, false
    );
}

function castVote(uint256 id, bool support) external {
    Proposal storage p = proposals[id];
    require(block.timestamp <= p.voteEnd, "closed");
    require(!hasVoted[id][msg.sender], "voted");
    uint256 weight = token.getPastVotes(msg.sender, p.snapshotBlock);
    require(weight > 0, "no power");
    hasVoted[id][msg.sender] = true;
    if (support) p.forVotes += weight;
    else p.againstVotes += weight;
}

function execute(uint256 id) external {
    Proposal storage p = proposals[id];
    require(block.timestamp > p.voteEnd && !p.executed, "not ready");
    uint256 total = p.forVotes + p.againstVotes;
    require(total >= QUORUM, "no quorum");
    require(p.forVotes > p.againstVotes, "defeated");
    p.executed = true;
    (bool ok, ) = p.target.call(p.data);
    require(ok, "failed");
}
